  destMountPath = '/opfs-append-dst-' + Date.now();
  destMountFilename = dstFname;
  FS.mkdir(destMountPath);
  createWriteOpfsFile(destMountPath, dstFname, size, handle);
  currentDestFile = new h5wasm.File(destMountPath + '/' + dstFname, 'a');

